// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.HashMap;
import java.util.Map;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Argument;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Compare;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.Constant;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.FragmentNode.DecodeInline;
import org.junit.jupiter.api.Test;

/** Access-fragment tests (fragment-fusion M4): run-bound restriction, probe family, SIP domains. */
class FragmentAccessTest {

	private static long orderedInt(long value) {
		return ValueIds.createId(ValueIds.T_ORD_INTEGER, value + ValueIds.ORDERED_BIAS);
	}

	/** A seekable ordered run over a sorted array (unsigned order; test values are all non-negative ids). */
	private static FragmentAccess.OrderedRunView run(long... ids) {
		return new FragmentAccess.OrderedRunView() {
			@Override
			public long size() {
				return ids.length;
			}

			@Override
			public long idAt(long index) {
				return ids[(int) index];
			}

			@Override
			public long seekFirstAtLeast(long from, long key) {
				for (long i = from; i < ids.length; i++) {
					if (Long.compareUnsigned(ids[(int) i], key) >= 0) {
						return i;
					}
				}
				return ids.length;
			}
		};
	}

	@Test
	void rangeRestrictionReplacesScanWithTwoSeeks() {
		long[] loHi = new long[2];
		FragmentAccess.orderedIntegerIdRange(ValueIds.T_ORD_INTEGER, 18, 65, loHi);
		FragmentAccess.OrderedRunView ages = run(orderedInt(5), orderedInt(17), orderedInt(18), orderedInt(40),
				orderedInt(64), orderedInt(65), orderedInt(90));
		long window = FragmentAccess.restrictToRange(ages, loHi[0], loHi[1]);
		assertThat(window).isNotEqualTo(FragmentAccess.NO_WINDOW);
		assertThat(FragmentAccess.windowStart(window)).isEqualTo(2);
		assertThat(FragmentAccess.windowEnd(window)).isEqualTo(5);
		// every id inside the window satisfies the range; every id outside violates it
		for (int i = FragmentAccess.windowStart(window); i < FragmentAccess.windowEnd(window); i++) {
			long value = ValueIds.orderedIntegerValue(ages.idAt(i));
			assertThat(value).isBetween(18L, 64L);
		}
	}

	@Test
	void unseekableRunFallsBackToPredicateVariant() {
		FragmentAccess.OrderedRunView unseekable = new FragmentAccess.OrderedRunView() {
			@Override
			public long size() {
				return 3;
			}

			@Override
			public long idAt(long index) {
				return orderedInt(index);
			}

			@Override
			public long seekFirstAtLeast(long from, long key) {
				return -1;
			}
		};
		assertThat(FragmentAccess.restrictToRange(unseekable, orderedInt(0), orderedInt(2)))
				.isEqualTo(FragmentAccess.NO_WINDOW);
	}

	private static FragmentAccess.AdjacencyView adjacency(Map<Long, long[]> neighbors) {
		return new FragmentAccess.AdjacencyView() {
			@Override
			public long find(long key) {
				return neighbors.containsKey(key) ? key + 1 : 0;
			}

			@Override
			public long size(long runHandle) {
				return neighbors.get(runHandle - 1).length;
			}

			@Override
			public long neighborAt(long runHandle, long index) {
				return neighbors.get(runHandle - 1)[(int) index];
			}
		};
	}

	@Test
	void probeFamilyStopsAtFirstWitnessAndComposesInnerPredicates() {
		Map<Long, long[]> graph = new HashMap<>();
		graph.put(1L, new long[] { orderedInt(3), orderedInt(9), orderedInt(20) });
		graph.put(2L, new long[] { orderedInt(3) });
		FragmentAccess.AdjacencyView adjacency = adjacency(graph);
		// inner predicate: neighbor >= 10
		LongPredicateFragment inner = FragmentCompiler.compilePredicate(FragmentIR.predicate(new Compare(
				FragmentCompareOp.GE, new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
				new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER))));
		FragmentBinding binding = FragmentBinding.of(orderedInt(10));
		assertThat(FragmentAccess.probe(adjacency, 1L, FragmentAccess.ProbeMode.EXISTS, inner, binding)).isEqualTo(1L);
		assertThat(FragmentAccess.probe(adjacency, 2L, FragmentAccess.ProbeMode.EXISTS, inner, binding)).isZero();
		assertThat(FragmentAccess.probe(adjacency, 2L, FragmentAccess.ProbeMode.NOT_EXISTS, inner, binding))
				.isEqualTo(1L);
		assertThat(FragmentAccess.probe(adjacency, 1L, FragmentAccess.ProbeMode.FIRST_WITNESS, inner, binding))
				.isEqualTo(orderedInt(20));
		// absent key: no witness
		assertThat(FragmentAccess.probe(adjacency, 9L, FragmentAccess.ProbeMode.EXISTS, null, FragmentBinding.EMPTY))
				.isZero();
		// no inner predicate: bare existence
		assertThat(FragmentAccess.probe(adjacency, 2L, FragmentAccess.ProbeMode.EXISTS, null, FragmentBinding.EMPTY))
				.isEqualTo(1L);
	}

	@Test
	void sipDomainsBuildSortedDedupedAndIntersect() {
		long[] domain = FragmentAccess.buildSipDomain(new long[] { 9, 3, 9, 1, 3, 7 }, 6);
		assertThat(domain).containsExactly(1, 3, 7, 9);
		long[] other = FragmentAccess.buildSipDomain(new long[] { 7, 2, 9 }, 3);
		assertThat(FragmentAccess.intersectSipDomains(domain, other)).containsExactly(7, 9);
		assertThat(FragmentAccess.intersectSipDomains(domain, new long[0])).isEmpty();
	}
}
